import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.Dh6DF7gt.js";const o="/ai-lab-smart-office/layout/office-layout-clean.png",u=JSON.parse('{"title":"办公室布局","description":"AI实验室办公室平面布局、功能分区和后续智能化点位规划基准。","frontmatter":{"title":"办公室布局","description":"AI实验室办公室平面布局、功能分区和后续智能化点位规划基准。"},"headers":[],"relativePath":"guide/office-layout.md","filePath":"guide/office-layout.md","lastUpdated":null}'),i={name:"guide/office-layout.md"};function l(n,t,s,c,h,p){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="办公室布局" tabindex="-1">办公室布局 <a class="header-anchor" href="#办公室布局" aria-label="Permalink to &quot;办公室布局&quot;">​</a></h1><h2 id="平面总览" tabindex="-1">平面总览 <a class="header-anchor" href="#平面总览" aria-label="Permalink to &quot;平面总览&quot;">​</a></h2><p><a href="/ai-lab-smart-office/layout/office-layout-clean.png"><img src="'+o+'" alt="AI实验室办公室平面布局"></a></p><p>点击图片可查看大图。当前版本在保留原始房间、门向和尺寸标注的基础上，完成了裁切、灰度校正、对比度增强和锐化，便于在线查阅与后续标注。</p><div class="warning custom-block"><p class="custom-block-title">图纸使用边界</p><p>本图来自现场平面图照片，适合作为空间定位和方案讨论的底图；施工尺寸、墙体条件和设备安装位置仍须以现场复核及正式施工图为准。</p></div><h2 id="功能分区" tabindex="-1">功能分区 <a class="header-anchor" href="#功能分区" aria-label="Permalink to &quot;功能分区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分区</th><th>主要空间</th><th>规划用途</th></tr></thead><tbody><tr><td>A 区</td><td>A大厅1、A大厅2、A大厅3</td><td>中部开放工位与主要协作区</td></tr><tr><td>A 区</td><td>A大厅4</td><td>独立交流、休息或小型接待区</td></tr><tr><td>B 区</td><td>B办公室1～3</td><td>东侧独立实验、研发或项目空间</td></tr><tr><td>C 区</td><td>C办公室1～5</td><td>西侧独立实验、研发或项目空间</td></tr><tr><td>D 区</td><td>D办公室1～3、D会议室</td><td>北侧项目空间与会议协作区</td></tr><tr><td>餐饮区</td><td>食堂、餐厅、灶台</td><td>用餐、茶歇与后勤保障</td></tr><tr><td>公共区</td><td>南侧前厅、前台、接待厅、走廊</td><td>访客接待、公共活动与通行</td></tr><tr><td>设施区</td><td>机房、厕所、电梯厅、入口</td><td>网络核心、基础设施与出入口</td></tr></tbody></table><p>图中的“办公室”和大厅编号暂作为房间定位代码使用；后续可根据 AI实验室的实际团队、设备和实验方向更新房间名称。</p><h2 id="智能化设计基准" tabindex="-1">智能化设计基准 <a class="header-anchor" href="#智能化设计基准" aria-label="Permalink to &quot;智能化设计基准&quot;">​</a></h2><p>后续专项图应统一以本页平面图为底图，并分层维护，避免在一张图上叠加过多信息：</p><ol><li><strong>网络与弱电层</strong>：机柜、交换机、AP、信息点、摄像头及线缆路径。</li><li><strong>照明与环境层</strong>：照明回路、人体存在、温湿度、空气质量与窗帘控制点。</li><li><strong>门禁与安防层</strong>：主要入口、机房、独立房间和公共区域的权限边界。</li><li><strong>设备与自动化层</strong>：控制面板、场景触发器、实验设备和能源计量点位。</li></ol><p>新增设备时，建议使用“分区—房间—设备类型—序号”的统一编号，例如 <code>C-03-AP-01</code>，并同步写入设备台账与验收记录。</p>',12)])])}const _=a(i,[["render",l]]);export{u as __pageData,_ as default};
